<?php require_once __DIR__.'/../includes/functions.php';require_role('admin');$rows=$pdo->query('SELECT n.id,u.email,n.title,n.is_read,n.created_at FROM notifications n JOIN users u ON u.id=n.user_id ORDER BY n.id DESC LIMIT 100')->fetchAll();$pageTitle='Notifications';$base='../';require __DIR__.'/../includes/header.php';?><div class='layout'><?php require __DIR__.'/../includes/sidebar.php';?><section class='content'><div class='card'><h1>Notifications</h1><div class='table-wrap'><table class='table'><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>